export default function Gallery() {
  return (
    <div className="page">
      <h1>Work Gallery</h1>

      <div className="gallery-grid">
        <img src="/g1.jpg" alt="" />
        <img src="/g2.jpg" alt="" />
        <img src="/g3.jpg" alt="" />
      </div>
    </div>
  );
}
